      firstCallMentionsCount: response1.result.includes('count'),
      secondCallFailed: response2.result.includes('validation failed'),
    }).toEqual({
      firstCallFailed: true,
      firstCallMentionsCount: true,
      secondCallFailed: true,
    });
  });

  it('rejects input with invalid types without logging or leaking the value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secret_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {secret: {type: 'string'}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('secret_tool', {secret: 123456789});
    expect(response.result).toContain('validation failed');
    expect(response.result).toContain('secret');
    expect(response.result).toContain('string');
    expect(response.result).not.toContain('123456789');
  });

  it('invokes the executor once and passes the input object through unchanged when validation succeeds', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let receivedInput: any;
    registry.register(
      {
        name: 'passthrough_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {id: {type: 'number'}},
          required: ['id'],
        },
      },
      async input => {
        executorCalls += 1;
        receivedInput = input;
        return 'ok';
      }
    );

    const inputObj = {id: 42, extra: 'kept', nested: {flag: true}};
    const response = await registry.execute('passthrough_tool', inputObj);

    expect(response).toEqual({result: 'ok'});
    expect(executorCalls).toBe(1);
    expect(receivedInput).toEqual({id: 42, extra: 'kept', nested: {flag: true}});
  });

  it('throws Unknown tool when executing an unregistered tool', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nonexistent', {})).rejects.toThrow('Unknown tool: nonexistent');
  });

  it('compiles static tool inputSchema at register time and reuses it without re-reading', async () => {
    const registry = new ToolRegistry();
    const schemaInstance: Record<string, unknown> = {
      type: 'object',
      properties: {count: {type: 'number'}},
      required: ['count'],
    };

    registry.register(
      {
        name: 'static_tool',
        description: 'test',
        inputSchema: schemaInstance,
      },
      async () => 'ok'
    );

    const response1 = await registry.execute('static_tool', {count: 'not-a-number'});
    // Mutate the original schema object
    schemaInstance.required = [];
    const response2 = await registry.execute('static_tool', {count: 'not-a-number'});

    expect(response1.result).toContain('validation failed');
    expect(response2.result).toContain('validation failed'); // still fails because compiled validator is reused
  });
});

